input.content:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  background-color: #f5f7fa;
  color: #333;
}

h1 {
  text-align: center;
  padding: 18px 0 10px;
  font-size: 1.6rem;
  color: #2c3e50;
}

.container {
  display: flex;
  gap: 24px;
  padding: 0 24px 24px;
  align-items: flex-start;
  max-width: 1600px;
  margin: 0 auto;
}

/* ---------- Bubble Chart ---------- */
#bubble-chart {
  flex: 1 1 55%;
  min-width: 500px;
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.08);
  padding: 16px;
}

#bubble-chart svg {
  display: block;
  width: 100%;
  height: auto;
}

circle.bubble {
  cursor: pointer;
  stroke: #fff;
  stroke-width: 1.2px;
  transition: stroke-width 0.15s;
}

circle.bubble:hover {
  stroke-width: 2.5px;
}

circle.bubble.highlighted {
  stroke: #222;
  stroke-width: 3px;
}

.bubble-label {
  pointer-events: none;
  fill: #fff;
  font-weight: 600;
  text-anchor: middle;
  dominant-baseline: central;
}

/* ---------- Legend ---------- */
.legend-item {
  cursor: default;
}

.legend-item text {
  font-size: 12px;
  fill: #444;
}

/* ---------- Tooltip ---------- */
.tooltip {
  position: absolute;
  padding: 10px 14px;
  background: rgba(30, 30, 30, 0.92);
  color: #fff;
  border-radius: 6px;
  font-size: 13px;
  line-height: 1.5;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.18s;
  max-width: 280px;
  z-index: 100;
}

.tooltip strong {
  font-size: 14px;
}

/* ---------- Data Table ---------- */
#data-table {
  flex: 1 1 40%;
  min-width: 380px;
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.08);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

#data-table h2 {
  padding: 14px 16px 10px;
  font-size: 1.1rem;
  color: #2c3e50;
  border-bottom: 1px solid #e9ecef;
}

.table-wrapper {
  overflow-y: auto;
  max-height: 640px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

thead {
  position: sticky;
  top: 0;
  z-index: 2;
}

thead th {
  background: #f0f2f5;
  padding: 10px 12px;
  text-align: left;
  font-weight: 600;
  color: #555;
  border-bottom: 2px solid #dee2e6;
  white-space: nowrap;
}

tbody tr {
  cursor: pointer;
  transition: background 0.12s;
}

tbody tr:nth-child(even) {
  background-color: #fafbfc;
}

tbody tr:hover {
  background-color: #e8f0fe;
}

tbody tr.highlighted {
  background-color: #fff3cd !important;
}

tbody td {
  padding: 8px 12px;
  border-bottom: 1px solid #eee;
  white-space: nowrap;
}

td.market-cap {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

