(async function () {
  // ── Helpers ──────────────────────────────────────────────────────────
  function formatMarketCap(v) {
    if (v == null || isNaN(v)) return "N/A";
    if (v >= 1e12) return (v / 1e12).toFixed(2) + "T";
    if (v >= 1e9) return (v / 1e9).toFixed(2) + "B";
    if (v >= 1e6) return (v / 1e6).toFixed(2) + "M";
    return v.toLocaleString();
  }

  // ── Load Data ────────────────────────────────────────────────────────
  const raw = await d3.csv("data/stock-descriptions.csv");

  const data = raw.map(d => ({
    ticker: d.ticker,
    sector: d.sector,
    name: d["full name"],
    marketCap: d.marketCap && d.marketCap !== "" ? +d.marketCap : null,
    country: d.country || null,
    website: d.website || null,
    isETF: d.sector === "ETF"
  }));

  // ── Dimensions ───────────────────────────────────────────────────────
  const chartWidth = 700;
  const chartHeight = 620;
  const margin = { top: 10, right: 10, bottom: 10, left: 10 };
  const innerW = chartWidth - margin.left - margin.right;
  const innerH = chartHeight - margin.top - margin.bottom;

  // ── Scales ───────────────────────────────────────────────────────────
  const sectors = [...new Set(data.map(d => d.sector))];

  const colorScale = d3.scaleOrdinal()
    .domain(sectors)
    .range(d3.schemeTableau10);

  const maxCap = d3.max(data, d => d.marketCap) || 1;
  const radiusScale = d3.scaleSqrt()
    .domain([0, maxCap])
    .range([6, 48]);

  const ETF_RADIUS = 14;

  function radius(d) {
    return d.isETF ? ETF_RADIUS : radiusScale(d.marketCap || 0);
  }

  // ── Cluster centres (grid layout) ────────────────────────────────────
  const gridCols = Math.ceil(Math.sqrt(sectors.length));
  const gridRows = Math.ceil(sectors.length / gridCols);
  const cellW = innerW / (gridCols + 0.4);
  const cellH = innerH / (gridRows + 0.4);
  const padX = (innerW - gridCols * cellW) / 2 + cellW / 2;
  const padY = (innerH - gridRows * cellH) / 2 + cellH / 2;

  const clusterCenters = {};
  sectors.forEach((s, i) => {
    const col = i % gridCols;
    const row = Math.floor(i / gridCols);
    clusterCenters[s] = {
      x: padX + col * cellW,
      y: padY + row * cellH
    };
  });

  // ── Tooltip ──────────────────────────────────────────────────────────
  const tooltip = d3.select("body").append("div").attr("class", "tooltip");

  // ── SVG ──────────────────────────────────────────────────────────────
  const svg = d3.select("#bubble-chart")
    .append("svg")
    .attr("viewBox", `0 0 ${chartWidth} ${chartHeight}`)
    .attr("preserveAspectRatio", "xMidYMid meet");

  const g = svg.append("g")
    .attr("transform", `translate(${margin.left},${margin.top})`);

  // ── Force Simulation ─────────────────────────────────────────────────
  const simulation = d3.forceSimulation(data)
    .force("x", d3.forceX(d => clusterCenters[d.sector].x).strength(0.35))
    .force("y", d3.forceY(d => clusterCenters[d.sector].y).strength(0.35))
    .force("collide", d3.forceCollide(d => radius(d) + 2).iterations(3))
    .force("charge", d3.forceManyBody().strength(2))
    .alphaDecay(0.02)
    .on("tick", ticked);

  // ── Bubbles ──────────────────────────────────────────────────────────
  const bubbles = g.selectAll("circle.bubble")
    .data(data)
    .join("circle")
    .attr("class", "bubble")
    .attr("r", d => radius(d))
    .attr("fill", d => colorScale(d.sector))
    .attr("data-ticker", d => d.ticker);

  // ── Labels inside bubbles ────────────────────────────────────────────
  const labels = g.selectAll("text.bubble-label")
    .data(data)
    .join("text")
    .attr("class", "bubble-label")
    .text(d => d.ticker)
    .style("font-size", d => {
      const r = radius(d);
      const len = d.ticker.length;
      return Math.min(r * 1.2 / (len * 0.52), r * 0.85, 14) + "px";
    });

  function ticked() {
    bubbles.attr("cx", d => d.x).attr("cy", d => d.y);
    labels.attr("x", d => d.x).attr("y", d => d.y);
  }

  // ── Bubble Interactions ──────────────────────────────────────────────
  bubbles
    .on("mouseover", (event, d) => {
      if (d.isETF) return; // no tooltip for ETFs
      tooltip.transition().duration(150).style("opacity", 1);
      tooltip.html(
        `<strong>${d.ticker}</strong><br/>` +
        `${d.name}<br/>` +
        `<em>${d.sector}</em>`
      )
        .style("left", (event.pageX + 14) + "px")
        .style("top", (event.pageY - 32) + "px");
    })
    .on("mousemove", (event) => {
      tooltip
        .style("left", (event.pageX + 14) + "px")
        .style("top", (event.pageY - 32) + "px");
    })
    .on("mouseout", () => {
      tooltip.transition().duration(200).style("opacity", 0);
    })
    .on("click", (event, d) => {
      highlight(d.ticker);
    });

  // ── Legend ────────────────────────────────────────────────────────────
  const legendG = svg.append("g")
    .attr("class", "legend")
    .attr("transform", `translate(${chartWidth - 175}, 16)`);

  const items = legendG.selectAll(".legend-item")
    .data(sectors)
    .join("g")
    .attr("class", "legend-item")
    .attr("transform", (d, i) => `translate(0, ${i * 22})`);

  items.append("rect")
    .attr("width", 14)
    .attr("height", 14)
    .attr("rx", 3)
    .attr("fill", d => colorScale(d));

  items.append("text")
    .attr("x", 20)
    .attr("y", 11)
    .text(d => d);

  // ── Data Table ───────────────────────────────────────────────────────
  const tableContainer = d3.select("#data-table");
  tableContainer.append("h2").text("Stock Details");

  const wrapper = tableContainer.append("div").attr("class", "table-wrapper");
  const tbl = wrapper.append("table");

  const theadRow = tbl.append("thead").append("tr");
  ["Ticker", "Company Name", "Sector", "Market Cap"].forEach(col => {
    theadRow.append("th").text(col);
  });

  const tbody = tbl.append("tbody");

  const tableRows = tbody.selectAll("tr")
    .data(data)
    .join("tr")
    .attr("data-ticker", d => d.ticker);

  tableRows.append("td").text(d => d.ticker);
  tableRows.append("td").text(d => d.name);
  tableRows.append("td").text(d => d.sector);
  tableRows.append("td").attr("class", "market-cap").text(d => formatMarketCap(d.marketCap));

  tableRows.on("click", (event, d) => {
    highlight(d.ticker);
  });

  // ── Linked Highlighting ──────────────────────────────────────────────
  let activeTicker = null;

  function highlight(ticker) {
    // Toggle off if already active
    if (activeTicker === ticker) {
      activeTicker = null;
      d3.selectAll("circle.bubble").classed("highlighted", false);
      d3.selectAll("tbody tr").classed("highlighted", false);
      return;
    }

    activeTicker = ticker;

    // Bubble
    d3.selectAll("circle.bubble").classed("highlighted", false);
    d3.select(`circle[data-ticker="${ticker}"]`).classed("highlighted", true);

    // Table row
    d3.selectAll("tbody tr").classed("highlighted", false);
    const row = d3.select(`tr[data-ticker="${ticker}"]`);
    row.classed("highlighted", true);

    // Scroll into view
    const node = row.node();
    if (node) {
      node.scrollIntoView({ behavior: "smooth", block: "center" });
    }
  }
})();
